div.script:

const SCRIPT_URL = "https://script.google.com/macros/s/AKfycbwMK-fvY5M7HnCcv8EjaCw6LO_jFB2N_PDw4RdM9R4rCqhTTa5XqmT8UeHQDzpDXgrC/exec"; 
const ID_NEGOZIO = "house_solutions"; 
const IL_TUO_NUMERO = "41764458866";
let datiNegozio = {};

function showContacts() {
  if (datiNegozio.count < datiNegozio.limite) {
    document.getElementById('btn-main').style.display = 'none';
    document.getElementById('contact-grid').style.display = 'flex';
    setTimeout(() => {
      document.getElementById('btn-main').style.display = 'inline-block';
      document.getElementById('contact-grid').style.display = 'none';
    }, 10000);
  }
}

async function caricaDati() {
  try {
    const response = await fetch(SCRIPT_URL + "?id=" + ID_NEGOZIO + "&t=" + new Date().getTime());
    datiNegozio = await response.json();
    const txt = document.getElementById('info-status');
    const bMain = document.getElementById('btn-main');
    const bAdmin = document.getElementById('btn-admin');
    aggiornaOrarioUI(datiNegozio.apeM, datiNegozio.chiM, datiNegozio.apeP, datiNegozio.chiP);
    if (datiNegozio.limite > 0 && datiNegozio.count >= datiNegozio.limite) {
      bMain.innerText = "LIMITE RAGGIUNTO";
      bMain.style.backgroundColor = "#ccc";
      bMain.disabled = true;
      txt.innerHTML = "<b>Contattaci per sbloccare o passare a un piano Base/Premium!</b>";
      bAdmin.style.display = "inline-block";
      bAdmin.href = "https://wa.me/" + IL_TUO_NUMERO + "?text=" + encodeURIComponent("Ciao! Vorrei sbloccare o passare al piano Premium per l'attività: " + ID_NEGOZIO);
    } else {
      bMain.innerText = "CONTATTA ORA";
      txt.innerText = "Accessi: " + datiNegozio.count + " / " + datiNegozio.limite;
      validaTasto('link-web', datiNegozio.url, datiNegozio.url);
      validaTasto('link-mail', "mailto:" + datiNegozio.email, datiNegozio.email);
      validaTasto('link-wa', "https://wa.me/" + datiNegozio.wa, datiNegozio.wa);
    }
  } catch (e) { document.getElementById('btn-main').innerText = "Errore Connessione"; }
}

function validaTasto(id, href, valore) {
  const el = document.getElementById(id);
  if (valore && valore.toString().trim() !== "" && valore.toString().toLowerCase() !== "undefined") {
    el.href = href; el.style.display = 'flex';
  } else { el.style.display = 'none'; }
}

function aggiornaOrarioUI(apeM, chiM, apeP, chiP) {
  const box = document.getElementById('status-orario');
  const testo = document.getElementById('testo-orario');
  const dot = document.getElementById('dot-orario');
  if (!apeM || !chiM) return;
  const oraAttuale = new Date();
  const adesso = oraAttuale.getHours().toString().padStart(2, '0') + ":" + oraAttuale.getMinutes().toString().padStart(2, '0');
  box.style.display = "block";
  if (adesso >= apeM.toString().substring(0,5) && adesso <= chiM.toString().substring(0,5)) {
    testo.innerText = "Aperto ora"; testo.style.color = "#28a745"; dot.innerHTML = "🟢";
  } else {
    testo.innerText = "Chiuso ora"; testo.style.color = "#d83c3c"; dot.innerHTML = "🔴";
  }
}

function registraClick() {
  fetch(SCRIPT_URL + "?id=" + ID_NEGOZIO + "&action=click");
  setTimeout(caricaDati, 1000);
}

caricaDati();
